        <input
          id="email"
          name="email"
          type="email"
          autocomplete="email"
          aria-describedby="emailError"
          required
        >
        <span class="error-message" id="emailError" aria-live="polite"></span>
      </div>

      <div class="form-field">
        <label for="phone">Phone number <span aria-hidden="true">(optional)</span></label>
        <input
          id="phone"
          name="phone"
          type="tel"
          autocomplete="tel"
          placeholder="555-123-4567"
          aria-describedby="phoneHelp phoneError"
        >
        <span class="helper-text" id="phoneHelp">Expected format: 555-123-4567 or (555) 123-4567.</span>
        <span class="error-message" id="phoneError" aria-live="polite"></span>
      </div>

      <button type="submit">Submit request</button>
      <p class="success-message" id="successMessage" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.querySelector("#supportForm");
    const fields = {
      fullName: {
        input: document.querySelector("#fullName"),
        error: document.querySelector("#fullNameError"),
        validate(value) {
          if (!value.trim()) {
            return "Full name is required.";
          }
          if (value.trim().length < 2) {
            return "Please enter your full name.";
          }
          return "";
        }
      },
      email: {
        input: document.querySelector("#email"),
        error: document.querySelector("#emailError"),
        validate(value) {
          if (!value.trim()) {
            return "Email address is required.";
          }
          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
            return "Please enter a valid email address.";
          }
          return "";
        }
      },
      phone: {
        input: document.querySelector("#phone"),
        error: document.querySelector("#phoneError"),
        validate(value) {
          const phone = value.trim();

          if (!phone) {
            return "";
          }
          if (!/^(\(\d{3}\)\s?|\d{3}[-.\s]?)\d{3}[-.\s]?\d{4}$/.test(phone)) {
            return "Please use a valid phone format, such as 555-123-4567.";
          }
          return "";
        }
      }
    };

    const successMessage = document.querySelector("#successMessage");

    function setFieldError(field, message) {
      field.error.textContent = message;
      field.input.setAttribute("aria-invalid", message ? "true" : "false");
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setFieldError(field, message);
      return !message;
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener("input", () => {
        validateField(field);
        successMessage.textContent = "";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const isValid = Object.values(fields).every(validateField);

      if (!isValid) {
        successMessage.textContent = "";
        return;
      }

      successMessage.textContent = "Thanks! Your support request is ready to send.";
      form.reset();
      Object.values(fields).forEach((field) => setFieldError(field, ""));
    });
  </script>
</body>
</html>
