 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Support Contact Form</title>
   <style>
     :root {
       --bg: #f4f7fb;
       --card: #ffffff;
       --text: #152238;
       --muted: #667085;
       --border: #d9e2ec;
       --primary: #2563eb;
       --primary-dark: #1d4ed8;
       --error: #dc2626;
       --success: #047857;
       --shadow: 0 24px 70px rgba(21, 34, 56, 0.14);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       display: grid;
       place-items: center;
       padding: 32px 16px;
       color: var(--text);
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top left, rgba(37, 99, 235, 0.18), transparent 32rem),
         linear-gradient(135deg, #eef4ff 0%, var(--bg) 52%, #f8fbff 100%);
     }

     .support-card {
       width: min(100%, 520px);
       padding: 40px;
       border: 1px solid rgba(217, 226, 236, 0.7);
       border-radius: 28px;
       background: rgba(255, 255, 255, 0.92);
       box-shadow: var(--shadow);
       backdrop-filter: blur(16px);
     }

     .eyebrow {
       margin: 0 0 10px;
       color: var(--primary);
       font-size: 0.78rem;
       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 7vw, 3rem);
       line-height: 1;
       letter-spacing: -0.06em;
     }

     .intro {
       margin: 16px 0 32px;
       color: var(--muted);
       line-height: 1.6;
     }

     .form-field {
       margin-bottom: 22px;
     }

     label {
       display: block;
       margin-bottom: 8px;
       font-size: 0.94rem;
       font-weight: 700;
     }

     input {
       width: 100%;
       padding: 14px 16px;
       border: 1px solid var(--border);
       border-radius: 14px;
       color: var(--text);
       font: inherit;
       background: #fbfdff;
       outline: none;
       transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
     }

     input:focus {
       border-color: var(--primary);
       background: #ffffff;
       box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
     }

     input[aria-invalid="true"] {
       border-color: var(--error);
       box-shadow: 0 0 0 4px rgba(220, 38, 38, 0.1);
     }

     .helper-text,
     .error-message {
       display: block;
       margin-top: 7px;
       font-size: 0.86rem;
       line-height: 1.4;
     }

     .helper-text {
       color: var(--muted);
     }

     .error-message {
       min-height: 1.2em;
       color: var(--error);
       font-weight: 600;
     }

     button {
       width: 100%;
       margin-top: 4px;
       padding: 15px 18px;
       border: 0;
       border-radius: 16px;
       color: #ffffff;
       font: inherit;
       font-weight: 800;
       cursor: pointer;
       background: linear-gradient(135deg, var(--primary), #4f46e5);
       box-shadow: 0 14px 28px rgba(37, 99, 235, 0.28);
       transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease;
     }

     button:hover {
       transform: translateY(-1px);
       box-shadow: 0 18px 34px rgba(37, 99, 235, 0.32);
       background: linear-gradient(135deg, var(--primary-dark), #4338ca);
     }

     button:focus-visible {
       outline: 4px solid rgba(37, 99, 235, 0.2);
       outline-offset: 3px;
     }

     .success-message {
       margin: 18px 0 0;
       color: var(--success);
       font-weight: 700;
       text-align: center;
     }

     @media (max-width: 520px) {
       .support-card {
         padding: 28px 22px;
         border-radius: 22px;
       }
     }
   </style>
 </head>
 <body>
   <main class="support-card">
     <p class="eyebrow">Support</p>
     <h1>Contact our team</h1>
     <p class="intro">Tell us how to reach you and a support specialist will follow up shortly.</p>

     <form id="supportForm" novalidate>
       <div class="form-field">
         <label for="fullName">Full name</label>
         <input
           id="fullName"
           name="fullName"
           type="text"
           autocomplete="name"
           aria-describedby="fullNameError"
           required
         >
         <span class="error-message" id="fullNameError" aria-live="polite"></span>
       </div>

       <div class="form-field">
         <label for="email">Email address</label>
         <input
           id="email"
           name="email"
           type="email"
           autocomplete="email"
           aria-describedby="emailError"
           required
         >
         <span class="error-message" id="emailError" aria-live="polite"></span>
       </div>

       <div class="form-field">
         <label for="phone">Phone number <span aria-hidden="true">(optional)</span></label>
         <input
           id="phone"
           name="phone"
           type="tel"
           autocomplete="tel"
           placeholder="555-123-4567"
           aria-describedby="phoneHelp phoneError"
         >
         <span class="helper-text" id="phoneHelp">Expected format: 555-123-4567 or (555) 123-4567.</span>
         <span class="error-message" id="phoneError" aria-live="polite"></span>
       </div>

       <button type="submit">Submit request</button>
       <p class="success-message" id="successMessage" aria-live="polite"></p>
     </form>
   </main>

   <script>
     const form = document.querySelector("#supportForm");
     const fields = {
       fullName: {
         input: document.querySelector("#fullName"),
         error: document.querySelector("#fullNameError"),
         validate(value) {
           if (!value.trim()) {
             return "Full name is required.";
           }
           if (value.trim().length < 2) {
             return "Please enter your full name.";
           }
           return "";
         }
       },
       email: {
         input: document.querySelector("#email"),
         error: document.querySelector("#emailError"),
         validate(value) {
           if (!value.trim()) {
             return "Email address is required.";
           }
           if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
             return "Please enter a valid email address.";
           }
           return "";
         }
       },
       phone: {
         input: document.querySelector("#phone"),
         error: document.querySelector("#phoneError"),
         validate(value) {
           const phone = value.trim();

           if (!phone) {
             return "";
           }
           if (!/^(\(\d{3}\)\s?|\d{3}[-.\s]?)\d{3}[-.\s]?\d{4}$/.test(phone)) {
             return "Please use a valid phone format, such as 555-123-4567.";
           }
           return "";
         }
       }
     };

     const successMessage = document.querySelector("#successMessage");

     function setFieldError(field, message) {
       field.error.textContent = message;
       field.input.setAttribute("aria-invalid", message ? "true" : "false");
     }

     function validateField(field) {
       const message = field.validate(field.input.value);
       setFieldError(field, message);
       return !message;
     }

     Object.values(fields).forEach((field) => {
       field.input.addEventListener("input", () => {
         validateField(field);
         successMessage.textContent = "";
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const isValid = Object.values(fields)
         .map(validateField)
         .every(Boolean);

       if (!isValid) {
         successMessage.textContent = "";
         return;
       }

       successMessage.textContent = "Thanks! Your support request is ready to send.";
       form.reset();
       Object.values(fields).forEach((field) => setFieldError(field, ""));
     });
   </script>
 </body>
 </html>

